const orderJsonKeys = (jsonObj) => {
  const ordered = {};
  Object.keys(jsonObj).sort().forEach(key => {
    ordered[key] = jsonObj[key];
  });
  return ordered;
}

// Check if file returned with content
if (Object.keys($input.all()[0].json).includes("content")) {
  // Decode base64 content and parse JSON
  const origWorkflow = JSON.parse(Buffer.from($input.all()[0].json.content, 'base64').toString());
  const n8nWorkflow = $input.all()[1].json;

  // Order JSON objects
  const orderedOriginal = orderJsonKeys(origWorkflow);
  const orderedActual = orderJsonKeys(n8nWorkflow);

  // Determine difference
  if (JSON.stringify(orderedOriginal) === JSON.stringify(orderedActual)) {
    $input.all()[0].json.github_status = "same";
  } else {
    $input.all()[0].json.github_status = "different";
    $input.all()[0].json.n8n_data_stringy = JSON.stringify(orderedActual, null, 2);
  }
  $input.all()[0].json.content_decoded = orderedOriginal;
// No file returned / new workflow
} else if (Object.keys($input.all()[0].json).includes("data")) {
  const origWorkflow = JSON.parse($input.all()[0].json.data);
  const n8nWorkflow = $input.all()[1].json;

  // Order JSON objects
  const orderedOriginal = orderJsonKeys(origWorkflow);
  const orderedActual = orderJsonKeys(n8nWorkflow);

  // Determine difference
  if (JSON.stringify(orderedOriginal) === JSON.stringify(orderedActual)) {
    $input.all()[0].json.github_status = "same";
  } else {
    $input.all()[0].json.github_status = "different";
    $input.all()[0].json.n8n_data_stringy = JSON.stringify(orderedActual, null, 2);
  }
  $input.all()[0].json.content_decoded = orderedOriginal;

} else {
  // Order JSON object
  const n8nWorkflow = $input.all()[1].json;
  const orderedActual = orderJsonKeys(n8nWorkflow);

  // Proper formatting
  $input.all()[0].json.github_status = "new";
  $input.all()[0].json.n8n_data_stringy = JSON.stringify(orderedActual, null, 2);
}

// Return items
return $input.all();

const runId = $execution.id;
const started = $execution.startedAt;
return $input.all().map((x) => ({
  json: { ...x.json, run_id: runId, workflow_run_started_at: started },
}));

// Composite Score Engine — transparent rules (edit to extend indicators)
const item = { ...$json };
const q = item.quote || {};
const dp = Number(q.dp) || 0;
const newsArr = Array.isArray(item.news) ? item.news : [];
const earn = item.earnings || {};
const earnList = Array.isArray(earn.earningsCalendar) ? earn.earningsCalendar : [];
const filingsRoot = item.filings;
let filingsArr = [];
if (Array.isArray(filingsRoot)) filingsArr = filingsRoot;
else if (filingsRoot && Array.isArray(filingsRoot.data)) filingsArr = filingsRoot.data;

let momentum = Math.max(-18, Math.min(18, dp * 2.2));

const posWords = /beat|growth|upgrade|strong|bull|record|expansion|deal|win|launch|innovation|surprise/i;
const negWords = /miss|weak|downgrade|lawsuit|probe|investigation|layoff|warning|delay|recall|breach|fraud|sec/i;
let pos = 0;
let neg = 0;
for (const n of newsArr.slice(0, 30)) {
  const h = `${n.headline || ''} ${n.summary || ''}`;
  if (posWords.test(h)) pos++;
  if (negWords.test(h)) neg++;
}
const newsSent = Math.max(-12, Math.min(12, (pos - neg) * 2));
const buzz = Math.max(0, Math.min(6, Math.floor(newsArr.length / 3)));

let earnBoost = 0;
const today = new Date();
for (const row of earnList) {
  const d = row.date ? new Date(row.date) : null;
  if (!d || isNaN(d.getTime())) continue;
  const days = (d - today) / 86400000;
  if (days >= 0 && days <= 5) earnBoost = Math.max(earnBoost, 10);
  else if (days > 5 && days <= 14) earnBoost = Math.max(earnBoost, 5);
}

const recentFilings = filingsArr.filter((f) => {
  const form = String(f.form || '').toUpperCase();
  return ['8-K', '10-Q', '10-K', '4'].includes(form);
});
const filingJitter = Math.min(8, recentFilings.length * 2);
const eightk = recentFilings.filter((f) => String(f.form || '').toUpperCase() === '8-K').length;
const riskFlag = eightk >= 2 ? 1 : 0;

let raw =
  50 +
  momentum +
  newsSent +
  buzz +
  earnBoost +
  filingJitter -
  riskFlag * 6 +
  (neg > pos ? -4 : 0);
const composite = Math.max(0, Math.min(100, Math.round(raw)));

return [
  {
    json: {
      ...item,
      composite_score: composite,
      headline_count: newsArr.length,
      score_breakdown: {
        momentum,
        newsSent,
        buzz,
        earnBoost,
        filingJitter,
        riskFlag,
        neg_headlines: neg,
        pos_headlines: pos,
      },
    },
  },
];

const item = { ...$json };
const sys =
  'You are an equity research assistant. Respond with JSON only. Keys: ticker, score (0-100, align with composite_score), sentiment (bullish|neutral|bearish), summary (<=120 words), key_signals (string array), red_flags (string array), alert_recommended (boolean), rationale_short (one sentence). No prose outside JSON.';
const user = `composite_score hint: ${item.composite_score}. Explain what changed, why it matters, main risks, whether it deserves watchlist attention.\nDATA:${JSON.stringify(item)}`;
item.openai_body = {
  model: 'gpt-4o-mini',
  temperature: 0.25,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: sys },
    { role: 'user', content: user },
  ],
};
return [{ json: item }];

const openai = $input.item.json;
const base = $('Code Composite Score').item.json;
let content = openai.choices?.[0]?.message?.content || '{}';
let ai;
try {
  ai = JSON.parse(content);
} catch (e) {
  ai = {
    ticker: base.ticker,
    score: base.composite_score,
    sentiment: 'neutral',
    summary: 'AI parse failed — inspect OpenAI response.',
    key_signals: [],
    red_flags: ['ai_parse_error'],
    alert_recommended: true,
    rationale_short: content.slice(0, 200),
  };
}
const thr = Number(base.alert_threshold ?? 70);
const scoreHi = Number(base.composite_score) >= thr;
const bearNews =
  String(ai.sentiment || '').toLowerCase() === 'bearish' &&
  (base.score_breakdown?.neg_headlines || 0) > 2;
const filingRisk = Number(base.score_breakdown?.riskFlag || 0) >= 1;
ai.alert_recommended =
  Boolean(ai.alert_recommended) || scoreHi || bearNews || filingRisk;
const record = {
  ...base,
  ai,
  composite_score: Number(ai.score) || base.composite_score,
  run_timestamp: new Date().toISOString(),
};
const t = record.ticker;
const s = record.composite_score;
const sent = ai.sentiment;
record.slack_alert_text =
  `🚨 *Stock Radar — Alert*\n*${t}* | Score *${s}* | *${sent}*\n• ${ai.rationale_short || ''}\n• ${(ai.summary || '').slice(0, 320)}`;
record.email_body = record.slack_alert_text.replace(/\*/g, '');
return [{ json: record }];

const start = (!$execution.startedAt ? new Date(0) : new Date($execution.startedAt));
const rows = $input
  .all()
  .map((i) => i.json)
  .filter((r) => r.timestamp && !isNaN(new Date(r.timestamp).getTime()))
  .filter((r) => new Date(r.timestamp) >= start);
rows.sort((a, b) => Number(b.composite_score || 0) - Number(a.composite_score || 0));
const top = rows.slice(0, 5);
const day = start.toISOString().slice(0, 10);
let md = `☕ *Stock Radar — Daily Brief*\n_${day}_ (Top ${top.length})\n\n`;
top.forEach((r, i) => {
  md += `${i + 1}. *${r.ticker}* — *${r.composite_score}* (${r.ai_sentiment || 'n/a'})\n   _${String(r.summary || '').slice(0, 160)}…_\n\n`;
});
if (!top.length) {
  md += '_No log rows matched this execution window — widen the Sheet read range or check timestamps._\n';
}
return [{ json: { digest_markdown: md, digest_plain: md.replace(/\*/g, ''), top } }];

const MAX = 49000;

function unwrap(x) {
  return x && typeof x === 'object' && x.json != null ? x.json : x;
}

function shrinkArray(items, mapRow, maxLen) {
  const rows = items.map(unwrap).map(mapRow);
  while (rows.length && JSON.stringify(rows).length > maxLen) {
    rows.pop();
  }
  let s = JSON.stringify(rows);
  if (s.length <= maxLen) return rows;
  while (rows.length) {
    const row = rows[rows.length - 1];
    for (const k of Object.keys(row)) {
      if (typeof row[k] === 'string' && row[k].length > 80) {
        row[k] = row[k].slice(0, 60) + '…';
      }
    }
    s = JSON.stringify(rows);
    if (s.length <= maxLen) return rows;
    rows.pop();
  }
  return [{ _note: 'rows_did_not_fit_under_limit', max: maxLen }];
}

function shrinkObject(v, maxLen) {
  if (v == null) return v;
  let s = JSON.stringify(v);
  if (s.length <= maxLen) return v;
  if (typeof v === 'object' && !Array.isArray(v)) {
    const o = { ...v };
    for (const k of Object.keys(o)) {
      if (typeof o[k] === 'string' && o[k].length > 6000) {
        o[k] = o[k].slice(0, 6000) + '…';
      }
    }
    s = JSON.stringify(o);
    if (s.length <= maxLen) return o;
    return {
      _truncated: true,
      ticker: o.ticker,
      sentiment: o.sentiment,
      summary: typeof o.summary === 'string' ? o.summary.slice(0, 12000) : undefined,
      rationale_short:
        typeof o.rationale_short === 'string' ? o.rationale_short.slice(0, 2000) : undefined,
    };
  }
  return { _truncated: true, type: typeof v, preview: s.slice(0, maxLen - 40) + '…' };
}

const j = { ...$input.item.json };

j.news = shrinkArray(
  Array.isArray(j.news) ? j.news : [],
  (a) => ({
    headline: String(a?.headline ?? '').slice(0, 320),
    source: a?.source,
    datetime: a?.datetime,
    url: String(a?.url ?? '').slice(0, 400),
  }),
  MAX,
);

j.filings = shrinkArray(
  Array.isArray(j.filings) ? j.filings : j.filings ? [j.filings] : [],
  (f) => ({
    form: f?.form,
    filedDate: f?.filedDate,
    filingUrl: String(f?.filingUrl ?? '').slice(0, 400),
  }),
  MAX,
);

j.earnings = shrinkObject(j.earnings, MAX);
j.score_breakdown = shrinkObject(j.score_breakdown, MAX);
j.ai = shrinkObject(j.ai, MAX);

return [{ json: j }];
